python3 -c "
import pandas as pd
import numpy as np

xl = pd.ExcelFile('data/test-rar.xlsx')
value_df = xl.parse('Value')
volume_df = xl.parse('Volume')

# Use string '2025'
idx_2025_val = value_df[value_df['.DESC'].astype(str) == '2025'].index[0]
idx_2025_vol = volume_df[volume_df['.DESC'].astype(str) == '2025'].index[0]

countries_value = {}
for col in value_df.columns[1:]:
    val = value_df.loc[idx_2025_val, col]
    if pd.notna(val):
        country = col.split(':')[0].strip()
        countries_value[country] = float(val)

avg_gold_price = 3202.8236082355647
countries_volume = {}
for col in volume_df.columns[1:]:
    val = volume_df.loc[idx_2025_vol, col]
    if pd.notna(val):
        country = col.split(':')[0].strip()
        countries_volume[country] = float(val)

additional_countries = {}
for country, volume in countries_volume.items():
    if country not in countries_value:
        additional_countries[country] = volume * avg_gold_price

final_step2_countries = {**countries_value, **additional_countries}

print('Countries in Value:', list(countries_value.keys()))
print('Additional countries from Volume:', list(additional_countries.keys()))
print('Final Step 2 data count:', len(final_step2_countries))

pd.Series(final_step2_countries).to_csv('step2_countries.csv')
"

